head.script:
scwin.onpageload = function() {
	progressbar1.animate(0,100,90000,function(){});
	progressbar2.animate(0,100,90000,function(){});

	//progressbar1.set(80);
};
scwin.onpageunload = function() {
};

scwin.progressbar2_displayFormatter = function(tmpVal) {
	// 항상 소수점 2자리
	var value = Number(tmpVal).toFixed(2) + "%";

	return value;
}


	scwin.isValidPercentageFormat = function(str) {
		//소수점이하 두자릿수 확인
		var regex = /^\d+\.\d{2}%$/;
		return regex.test(str);
	}
	scwin.checkVal = function() {
		const checkValue = WebSquare.wUnit.getDomById('progressbar1_bar').innerText;
		return scwin.isValidPercentageFormat(checkValue);
	}

	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "1500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
